/* ==========================================================================
   Constraints-Led Return to Performance — shared lesson stylesheet
   Every lesson and reference document links this file. Do not inline styles
   in a lesson; add a reusable component here instead.
   Tufte-influenced: generous margins, one column, footnote-weight citations.
   Designed to print cleanly on US Letter.
   ========================================================================== */

:root {
  --ink:        #1a1a18;
  --ink-soft:   #55534e;
  --ink-faint:  #8a8781;
  --paper:      #fdfcf9;
  --rule:       #ddd9d0;
  --green:      #154734;  /* Baylor green */
  --gold:       #ffb81c;  /* Baylor gold  */
  --warn-bg:    #fff8e6;
  --note-bg:    #f2f5f3;

  --serif: "Iowan Old Style", "Palatino Linotype", Palatino, Georgia, serif;
  --sans:  "Inter", -apple-system, BlinkMacSystemFont, "Segoe UI", Helvetica, sans-serif;
  --mono:  "SF Mono", "JetBrains Mono", Menlo, Consolas, monospace;

  --measure: 34rem;   /* ~66 characters. Do not widen. */
}

* { box-sizing: border-box; }

body {
  margin: 0 auto;
  padding: 4rem 2rem 8rem;
  max-width: 52rem;
  background: var(--paper);
  color: var(--ink);
  font-family: var(--serif);
  font-size: 1.0625rem;
  line-height: 1.62;
  -webkit-font-smoothing: antialiased;
}

/* --- Typography ---------------------------------------------------------- */

h1, h2, h3 { font-family: var(--sans); font-weight: 650; line-height: 1.22; color: var(--green); }
h1 { font-size: 2.1rem; margin: 0 0 .4rem; letter-spacing: -.02em; }
h2 { font-size: 1.35rem; margin: 3rem 0 .8rem; }
h3 { font-size: 1.05rem; margin: 2rem 0 .5rem; color: var(--ink); }

p, ul, ol { max-width: var(--measure); }
p  { margin: 0 0 1.1rem; }
ul, ol { padding-left: 1.2rem; margin: 0 0 1.1rem; }
li { margin-bottom: .4rem; }

a { color: var(--green); text-underline-offset: 2px; text-decoration-thickness: 1px; }
a:hover { background: var(--gold); text-decoration: none; }

strong { font-weight: 650; }
code { font-family: var(--mono); font-size: .875em; background: var(--note-bg); padding: .1em .35em; border-radius: 3px; }

/* --- Lesson header ------------------------------------------------------- */

.eyebrow {
  font-family: var(--sans); font-size: .72rem; font-weight: 600;
  letter-spacing: .13em; text-transform: uppercase; color: var(--ink-faint);
  margin: 0 0 .6rem;
}
.subtitle {
  font-family: var(--sans); font-size: 1.05rem; font-weight: 400;
  color: var(--ink-soft); max-width: var(--measure); margin: 0 0 2.5rem;
}
.lesson-meta {
  font-family: var(--sans); font-size: .8rem; color: var(--ink-faint);
  border-top: 1px solid var(--rule); padding-top: .7rem; margin-bottom: 2.5rem;
}

/* --- Callouts ------------------------------------------------------------ */

.callout {
  max-width: var(--measure);
  border-left: 3px solid var(--green);
  background: var(--note-bg);
  padding: 1rem 1.2rem; margin: 1.6rem 0; border-radius: 0 4px 4px 0;
}
.callout > :last-child { margin-bottom: 0; }
.callout--field  { border-left-color: var(--gold); background: var(--warn-bg); }
.callout--myth   { border-left-color: #b03a2e; background: #fdf1ef; }
.callout__label {
  display: block; font-family: var(--sans); font-size: .7rem; font-weight: 700;
  letter-spacing: .1em; text-transform: uppercase; color: var(--ink-faint); margin-bottom: .4rem;
}

/* --- Citations ----------------------------------------------------------- */

.cite {
  font-family: var(--sans); font-size: .8rem; line-height: 1.45;
  color: var(--ink-soft); max-width: var(--measure);
  border-left: 2px solid var(--rule); padding-left: .8rem; margin: 1.2rem 0;
}
.cite a { color: var(--ink-soft); }

.primary-source {
  max-width: var(--measure); margin: 2.5rem 0;
  border: 1px solid var(--rule); border-top: 3px solid var(--gold);
  padding: 1.1rem 1.3rem; border-radius: 0 0 4px 4px; background: #fff;
}

/* --- Constraint table (the workhorse component) -------------------------- */

table { border-collapse: collapse; width: 100%; margin: 1.6rem 0; font-family: var(--sans); font-size: .875rem; }
th, td { text-align: left; padding: .6rem .8rem; border-bottom: 1px solid var(--rule); vertical-align: top; }
th { font-weight: 650; color: var(--green); border-bottom-width: 2px; }
tbody tr:hover { background: var(--note-bg); }

.constraint-performer  td:first-child { border-left: 3px solid #2e6f9e; }
.constraint-task       td:first-child { border-left: 3px solid var(--green); }
.constraint-environment td:first-child { border-left: 3px solid var(--gold); }

/* --- Control → chaos progression bar ------------------------------------- */

.continuum { max-width: var(--measure); margin: 1.8rem 0; font-family: var(--sans); font-size: .78rem; }
.continuum__bar {
  height: 10px; border-radius: 5px;
  background: linear-gradient(90deg, #2e6f9e 0%, #4b9b6e 45%, var(--gold) 78%, #b03a2e 100%);
}
.continuum__labels { display: flex; justify-content: space-between; color: var(--ink-faint); margin-top: .4rem; }

/* --- Quiz ---------------------------------------------------------------- */

.quiz { max-width: var(--measure); margin: 2rem 0; border: 1px solid var(--rule); border-radius: 5px; padding: 1.2rem 1.3rem; background: #fff; }
.quiz__q { font-family: var(--sans); font-weight: 600; margin: 0 0 .9rem; }
.quiz__opt {
  display: block; width: 100%; text-align: left; font: inherit;
  font-family: var(--sans); font-size: .9rem;
  background: var(--paper); border: 1px solid var(--rule); border-radius: 4px;
  padding: .6rem .8rem; margin-bottom: .5rem; cursor: pointer;
  transition: background .12s ease, border-color .12s ease;
}
.quiz__opt:hover { border-color: var(--green); }
.quiz__opt.is-correct { background: #e8f3ec; border-color: var(--green); }
.quiz__opt.is-wrong   { background: #fdf1ef; border-color: #b03a2e; }
.quiz__feedback { font-family: var(--sans); font-size: .85rem; color: var(--ink-soft); margin-top: .8rem; min-height: 1.2em; }

/* --- Footer / next steps ------------------------------------------------- */

.ask-teacher {
  max-width: var(--measure); margin-top: 3.5rem; padding-top: 1.2rem;
  border-top: 1px solid var(--rule);
  font-family: var(--sans); font-size: .85rem; color: var(--ink-soft);
}

/* --- Print --------------------------------------------------------------- */

@media print {
  body { padding: 0; font-size: 11pt; background: #fff; }
  .quiz__opt { break-inside: avoid; }
  .callout, .primary-source, .quiz, table { break-inside: avoid; }
  a { color: var(--ink); text-decoration: none; }
  a[href^="http"]::after { content: " (" attr(href) ")"; font-size: .75em; color: var(--ink-faint); word-break: break-all; }
  .ask-teacher { display: none; }
}
