/* ==========================================================================
   quiz.js — retrieval-practice widget shared by every lesson.

   Markup:
     <div class="quiz" data-quiz>
       <p class="quiz__q">Question text</p>
       <button class="quiz__opt" data-feedback="Coach the fix here.">Option</button>
       <button class="quiz__opt" data-correct data-feedback="Why this is right.">Option</button>
       <p class="quiz__feedback" aria-live="polite"></p>
     </div>

   Behaviour (per NOTES.md, feedback must coach, not just correct):
   - Wrong option: marked, its data-feedback shown, learner may try again.
   - Correct option: marked, its data-feedback shown, all options locked.
   - Every option must be the same length. The script does not enforce that;
     the author does.
   ========================================================================== */
(function () {
  function init(quiz) {
    var opts = quiz.querySelectorAll('.quiz__opt');
    var out = quiz.querySelector('.quiz__feedback');
    var done = false;

    Array.prototype.forEach.call(opts, function (opt) {
      opt.addEventListener('click', function () {
        if (done) return;
        var correct = opt.hasAttribute('data-correct');
        var msg = opt.getAttribute('data-feedback') || '';
        if (correct) {
          opt.classList.add('is-correct');
          if (out) out.textContent = 'Right. ' + msg;
          done = true;
          Array.prototype.forEach.call(opts, function (o) { o.disabled = true; });
        } else {
          opt.classList.add('is-wrong');
          opt.disabled = true;
          if (out) out.textContent = 'Not this one. ' + msg + ' Try again.';
        }
      });
    });
  }

  function boot() {
    var quizzes = document.querySelectorAll('[data-quiz]');
    Array.prototype.forEach.call(quizzes, init);
  }

  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', boot);
  } else {
    boot();
  }
})();

